import {ToolRegistry} from './registry.js';

describe('ToolRegistry validation', () => {
  it('rejects input with a missing required property without calling executor', async () => {
    const registry = new ToolRegistry();
    let executorCalls = 0;

    registry.register(
      {
        name: 'test_tool',
        description: 'Test tool',
        inputSchema: {
          type: 'object',
          properties: {location: {type: 'string'}},
          required: ['location'],
        },
      },
      async () => {
        executorCalls += 1;
        return 'result';
      }
    );

    const response = await registry.execute('test_tool', {});

    expect({
      executorCalls,
      mentionsLocation: response.result.includes('location'),
    }).toEqual({
      executorCalls: 0,
      mentionsLocation: true,
    });
  });

  it('rejects a wrong-typed property naming the field and expected type without leaking the value', async () => {
    const registry = new ToolRegistry();
    let executorCalls = 0;

    registry.register(
      {
        name: 'test_type_error',
        description: 'Test tool',
        inputSchema: {
          type: 'object',
          properties: {ssn: {type: 'string'}},
          required: ['ssn'],
        },
      },
      async () => {
        executorCalls += 1;
        return 'result';
      }
    );

    const response = await registry.execute('test_type_error', {ssn: 123456789});

    expect({
      executorCalls,
      mentionsSsn: response.result.includes('ssn'),
      mentionsString: response.result.includes('string'),
      leaksValue: response.result.includes('123456789'),
    }).toEqual({
      executorCalls: 0,
      mentionsSsn: true,
      mentionsString: true,
      leaksValue: false,
    });
  });

  it('passes valid input with unlisted extra properties through to executor unchanged', async () => {
    const registry = new ToolRegistry();
    let capturedInput: Record<string, unknown> | undefined;

    registry.register(
      {
        name: 'test_extra_props',
        description: 'Test tool',
        inputSchema: {
          type: 'object',
          properties: {name: {type: 'string'}},
          required: ['name'],
        },
      },
      async input => {
        capturedInput = input;
        return 'result';
      }
    );

    const testInput = {name: 'Alice', extra: 'value', nested: {key: 'data'}};
    const response = await registry.execute('test_extra_props', testInput);

    expect({
      input: capturedInput,
      resultIsString: typeof response.result === 'string',
    }).toEqual({
      input: testInput,
      resultIsString: true,
    });
  });

  it('throws at register time naming the tool when a static inputSchema cannot be compiled', () => {
    const registry = new ToolRegistry();

    expect(() =>
      registry.register(
        {
          name: 'broken_schema_tool',
          description: 'Has an invalid schema',
          inputSchema: {
            type: 'object',
            properties: {location: {type: 'not-a-valid-type'}},
          },
        },
        async () => 'unreachable'
      )
    ).toThrow(/broken_schema_tool/);
  });

  it('throws Unknown tool when executing an unregistered tool name', async () => {
    const registry = new ToolRegistry();

    await expect(registry.execute('nonexistent_tool', {})).rejects.toThrow('Unknown tool: nonexistent_tool');
  });

  it('compiles a static tool schema once across multiple execute calls', async () => {
    const registry = new ToolRegistry();
    let executeCount = 0;

    registry.register(
      {
        name: 'static_schema_tool',
        description: 'Tool with static schema',
        inputSchema: {
          type: 'object',
          properties: {value: {type: 'string'}},
          required: ['value'],
        },
      },
      async () => {
        executeCount += 1;
        return 'result';
      }
    );

    // Execute 10 times with valid input
    for (let i = 0; i < 10; i++) {
      await registry.execute('static_schema_tool', {value: `test${i}`});
    }

    expect(executeCount).toBe(10);
  });

  it('validates function-valued tool definitions against current schema on each call', async () => {
    const registry = new ToolRegistry();
    let schemaVersion = 1;
    let executeCount = 0;

    registry.register(
      () => ({
        name: 'dynamic_schema_tool',
        description: 'Tool with dynamic schema',
        inputSchema: {
          type: 'object',
          properties: {value: {type: 'string'}},
          required: ['value', ...['extra' as any].filter(() => schemaVersion === 2)],
        },
      }),
      async () => {
        executeCount += 1;
        return 'result';
      }
    );

    // First call - schema v1 requires only 'value'
    const response1 = await registry.execute('dynamic_schema_tool', {value: 'test'});
    expect(response1.result).toBe('result');

    // Change schema version
    schemaVersion = 2;

