it('validates function-valued tool definitions against current schema on each call', async () => {
  const registry = new ToolRegistry();
  let schemaVersion = 1;
  let executeCount = 0;

  registry.register(
    () => ({
      name: 'dynamic_schema_tool',
      description: 'Tool with dynamic schema',
      inputSchema: {
        type: 'object',
        properties: {value: {type: 'string'}},
        required: ['value', ...['extra' as any].filter(() => schemaVersion === 2)],
      },
    }),
    async () => {
      executeCount += 1;
      return 'result';
    }
  );

  // First call - schema v1 requires only 'value'
  const response1 = await registry.execute('dynamic_schema_tool', {value: 'test'});
  expect(response1.result).toBe('result');

  // Change schema version
  schemaVersion = 2;

  // Second call - schema v2 requires 'value' and 'extra', call with missing 'extra' should fail
  const response2 = await registry.execute('dynamic_schema_tool', {value: 'test'});
  expect(response2.result).toContain('required');
  expect(executeCount).toBe(1); // Executor only called once (first valid call)
});

